    public event ButtonsHandler Buttons;

    /// <summary>Pad description event sequence complete</summary>
    public delegate void DoneHandler();

    /// <summary>Pad description event sequence complete</summary>
    public event DoneHandler Done;

    /// <summary>Physical button state</summary>
    public delegate void ButtonHandler(uint time, uint button, ButtonState state);

    /// <summary>Physical button state</summary>
    public event ButtonHandler Button;

    /// <summary>Enter event</summary>
    public delegate void EnterHandler(uint serial, ZwpTabletV2 tablet, WlSurface surface);

    /// <summary>Enter event</summary>
    public event EnterHandler Enter;

    /// <summary>Leave event</summary>
    public delegate void LeaveHandler(uint serial, WlSurface surface);

    /// <summary>Leave event</summary>
    public event LeaveHandler Leave;

    /// <summary>Pad removed event</summary>
    public delegate void RemovedHandler();

    /// <summary>Pad removed event</summary>
    public event RemovedHandler Removed;

    protected override void DispatchEvent(uint opcode, WlArgument* args)
    {
        switch (opcode)
        {
            case 0:
            {
                var padGroupCreated = Adopt<ZwpTabletPadGroupV2>(args[0].o, Version);
                Group?.Invoke(padGroupCreated);
                break;
            }
            case 1:
            {
                Path?.Invoke(WaylandString.Read(args[0].s) ?? string.Empty);
                break;
            }
            case 2:
            {
                Buttons?.Invoke(args[0].u);
                break;
            }
            case 3:
            {
                Done?.Invoke();
                break;
            }
            case 4:
            {
                Button?.Invoke(args[0].u, args[1].u, (ButtonState)args[2].u);
                break;
            }
            case 5:
            {
                Enter?.Invoke(args[0].u, Find<ZwpTabletV2>(args[1].o), Find<WlSurface>(args[2].o));
                break;
            }
            case 6:
            {
                Leave?.Invoke(args[0].u, Find<WlSurface>(args[1].o));
                break;
            }
            case 7:
            {
                Removed?.Invoke();
                break;
            }
        }
    }
}

/// <summary>Pad dial</summary>
public sealed unsafe partial class ZwpTabletPadDialV2 : WaylandProxy, IWaylandInterface<ZwpTabletPadDialV2>
{
    public const string InterfaceName = "zwp_tablet_pad_dial_v2";
    public const uint InterfaceVersion = 2;

    private ZwpTabletPadDialV2(nint handle, uint version) : base(handle, version)
    {
    }

    public static WlInterface* Interface => WaylandInterfaces.ZwpTabletPadDialV2;

    static ZwpTabletPadDialV2 IWaylandInterface<ZwpTabletPadDialV2>.Create(nint handle, uint version) => new(handle, version);

    /// <summary>Set compositor feedback</summary>
    public void SetFeedback(string description, uint serial)
    {
        using var descriptionUtf8 = new WaylandString(description);
        var wlArgs = stackalloc WlArgument[2];
        wlArgs[0].s = descriptionUtf8.Pointer;
        wlArgs[1].u = serial;
        Marshal(0, null, Version, wlArgs);
    }

    /// <summary>Destroy the dial object</summary>
    public void Destroy()
    {
        var wlArgs = stackalloc WlArgument[1];
        MarshalDestroy(1, wlArgs);
    }

    /// <summary>Delta movement</summary>
    public delegate void DeltaHandler(int value120);

    /// <summary>Delta movement</summary>
    public event DeltaHandler Delta;

    /// <summary>End of a dial event sequence</summary>
    public delegate void FrameHandler(uint time);

    /// <summary>End of a dial event sequence</summary>
    public event FrameHandler Frame;

    protected override void DispatchEvent(uint opcode, WlArgument* args)
    {
        switch (opcode)
        {
            case 0:
            {
                Delta?.Invoke(args[0].i);
                break;
            }
            case 1:
            {
                Frame?.Invoke(args[0].u);
                break;
            }
        }
    }
}
